llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Propranolol absolute oral bioavailability in humans was 30–35% after oral tablets vs IV, an affirmative F≥20% measurement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Bevantolol absolute bioavailability averaged 57% (range 26–98%) in healthy volunteers after a 50 mg oral dose vs IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "KNI-272 post-prandial absolute bioavailability was 36.40% in patients after a 6.6 mg/kg capsule, directly relevant to the fed-state condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Diacetolol mean absolute oral bioavailability was 0.426 ± 0.068 after an 800 mg oral dose vs IV in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "FK788, an aryloxyacetic acid-containing compound, had a calculated oral bioavailability of 55% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Etodolac, a lipophilic carboxylic acid, has an absolute oral bioavailability of 0.80 in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Methocarbamol oral bioavailability in humans was 90%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Penbutolol immediate-release absolute oral bioavailability in humans was 90%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "One propranolol record calculated F as 0.17 at 80 mg, a sub-20% value; this is an outlier against multiple higher propranolol measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "KNI-272 in children given an Ora-Plus formulation had mean absolute F of 12%, a sub-20% value; this is pediatric/formulation-specific and outweighed by adult and post-prandial values.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Across high-transfer human absolute bioavailability measurements, the large majority report F ≥ 20% (30–94%), including a post-prandial KNI-272 value and carboxylic acid-containing drugs such as etodolac and FK788. Isolated sub-20% records are outliers or pediatric/formulation-specific. Therefore the query is predicted high at the F≥20% threshold under fed conditions.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule under fed conditions.",
    "Most evidence molecules are not prostaglandin analogues; prostaglandin-specific first-pass metabolism is not directly captured.",
    "Conflicting propranolol record (17%) and pediatric KNI-272 record (12%) introduce minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

